content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-30-pet-feeder-001

=== 用户原始指令 (query.txt) ===
弄个图卡,带出粮数字,点导航去宠物店,日历有安排,粮少提醒

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "弄个图卡,带出粮数字,点导航去宠物店,日历有安排,粮少提醒",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToIntent",
      "args": {
        "intentName": "StartNavigate",
        "params": {
          "dstLocation": {
            "latitude": "22.3193",
            "longitude": "114.1694"
          },
          "trafficpe": "Walk"
        }
      }
    }
  ],
  "dataModelSchema": {
    "feeder": {
      "title": {
        "type": "string",
        "description": "宠物喂食卡片标题",
        "sampleValue": "宠物喂食"
      },
      "current": {
        "feedAmountText": {
          "type": "string",
          "description": "本次已出粮数量展示文本",
          "sampleValue": "42g"
        },
        "feedCaption": {
          "type": "string",
          "description": "出粮数量说明",
          "sampleValue": "本次出粮"
        }
      },
      "status": {
        "grainWarningText": {
          "type": "string",
          "description": "余粮不足提醒状态",
          "sampleValue": "粮少提醒"
        },
        "grainLevelText": {
          "type": "string",
          "description": "宠物粮剩余量展示文本",
          "sampleValue": "余粮 12%"
        }
      },
      "destination": {
        "petStoreName": {
          "type": "string",
          "description": "导航目标宠物店名称",
          "sampleValue": "附近宠物店"
        },
        "latitude": {
          "type": "string",
          "description": "导航目标纬度",
          "sampleValue": "22.3193"
        },
        "longitude": {
          "type": "string",
          "description": "导航目标经度",
          "sampleValue": "114.1694"
        }
      }
    },
    "data": {
      "calendar": {
        "items": [
          {
            "entityId": {
              "type": "string",
              "description": "日程唯一标识符",
              "sampleValue": "pet-feed-001"
            },
            "title": {
              "type": "string",
              "description": "日历中的喂食安排标题",
              "sampleValue": "加粮"
            },
            "dtStart": {
              "type": "string",
              "description": "喂食安排开始时间",
              "sampleValue": "18:30"
            },
            "dtEnd": {
              "type": "string",
              "description": "喂食安排结束时间",
              "sampleValue": "18:45"
            }
          }
        ]
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/bell_fill.svg",
      "description": "铃铛实心图标，适合表示宠物粮不足的提醒状态，需放在浅色图标底板上使用。"
    },
    {
      "src": "resources/base/media/calendar_fill.svg",
      "description": "日历实心图标，适合表示当天喂食安排或日历事件，需放在浅色信息面板中使用。"
    }
  ]
}

